import{z as A,x as l,o as r,c as p,q as E,j as n,D as e,d as s,s as o,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"状态价格到 SDF","description":"","frontmatter":{"title":"状态价格到 SDF","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/state-price-sdf-bridge.md","filePath":"econ/state-price-sdf-bridge.md","lastUpdated":1791063341000}'),d={name:"econ/state-price-sdf-bridge.md"};function h(B,a,c,b,D,_){const m=l("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="状态价格到-sdf" tabindex="-1">状态价格到 SDF <a class="header-anchor" href="#状态价格到-sdf" aria-label="Permalink to &quot;状态价格到 SDF&quot;">​</a></h1><div class="epigraph"><p>Arrow 价格除以概率就是一期随机折现因子；密度过程就是多期的 $m$。两套语言指同一线性泛函。</p><footer>—— 据 Arrow 1964；Harrison–Kreps 1979；Hansen and Richard, Econometrica 1987</footer></div><p><a href="/econ/harrison-kreps-martingale">上一课</a>把 FTAP 写成鞅。主干里 <a href="/econ/state-prices">状态价格</a> 与 <a href="/econ/stochastic-discount-factor">SDF</a> 已经分别出现。本课缺口是<strong>一座桥</strong>：后文 Lucas 树要用 \\(u&#39;(c)\\) 同时说出 \\(q\\)、\\(m\\) 与 \\(\\mathbb{Q}\\)，不允许三套符号各讲各的。不重推存在性，不校准消费。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限状态：Arrow 价格 \\(q_s\\)，物理概率 \\(\\pi_s\\)，一期 SDF \\(m_s=q_s/\\pi_s\\)（差计价因子）。于是 \\(p=\\sum q_s x_s=\\mathrm{E}[m x]\\)。风险中性概率 \\(\\mathbb{Q}(s)\\propto q_s\\)，\\(p=B^{-1}\\mathrm{E}^{\\mathbb{Q}}[x]\\)。三行是同一内积。多期：状态价格变成过程，\\(m_{t,t+k}\\) 是从 \\(t\\) 到 \\(t+k\\) 的随机折现，\\(Z_t\\) 是 \\(\\mathrm{d}\\mathbb{Q}/\\mathrm{d}\\mathbb{P}\\) 的密度，\\(m\\) 把 \\(Z\\) 的增量与利率折现绑在一起。Hansen–Richard 强调条件信息：所有等式在 \\(\\mathrm{E}[\\,\\cdot\\mid\\mathcal{F}_t]\\) 上成立，投影随信息变，会计不变。</p><p>缺口是强迫后课只用一套会计。信息课序的部分揭示，说的是 \\(\\mathcal{F}_t\\) 里有没有别人的信号；SDF 课序的条件期望，说的是给定已经写入价格的信息如何定价。桥在「信息集」上相切，对象仍不同。</p><p><span class="marginnote">术语翻译：随机折现因子（SDF）是一张「每状态赔率表」：状态 \\(s\\) 里的每 1 元支付，今天值 \\(m_s\\) 元。坏状态人人缺钱，\\(m_s\\) 就大；好状态 \\(m_s\\) 小。资产价格＝各状态的支付乘上各自的 \\(m\\) 再加总。</span></p><p><span class="marginnote">完全市场：\\(q\\) 唯一，\\(m\\) 唯一，\\(\\mathbb{Q}\\) 唯一。不完全：三者都是集合，但集合一一对应——选一个 \\(q\\gg 0\\) 即选一个 \\(m\\gt 0\\) 即选一个 EMM。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写翻译表，不再推导。计价：若 \\(B\\) 是无风险账户，\\(q\\) 已含时间折现，\\(m\\) 的期望 \\(\\mathrm{E}[m]=1/R^f\\)。欧拉：均衡再加 \\(m=\\beta u&#39;(c_{t+1})/u&#39;(c_t)\\)，这是从可行集对偶走进偏好。FTAP 不要求这一步；Lucas 树要求。CAPM 是再加「\\(m\\) 对市场回报线性」，见 <a href="/econ/capm-theory">CAPM 作为均衡</a>，本课不加。</p>',10)),(r(),n(i,null,{default:e(()=>[o(m,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20QSP%5B%22%E7%8A%B6%E6%80%81%E4%BB%B7%E6%A0%BC%20q%22%5D%20--%3E%20M%5B%22m%20%3D%20q%20%2F%20%CF%80%22%5D%0A%20%20M%20--%3E%20EQ%5B%22E%5Bm%20x%5D%20%3D%20p%22%5D%0A%20%20QSP%20--%3E%20RN%5B%22Q%20%E5%BD%92%E4%B8%80%E5%8C%96%20q%22%5D%0A%20%20RN%20--%3E%20MG%5B%22%E6%8A%98%E7%8E%B0%E4%BB%B7%E6%A0%BC%20Q-%E9%9E%85%22%5D%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%3A%20m%20%3D%20MRS%22%5D%20--%3E%20M%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与接口课对照：买卖价差意味着没有单一 \\(p\\)，翻译表对 ask 与 bid 各写一行，或对中间价写近似。桥不消灭价差，只在无摩擦处把符号焊死。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"机制是同一对偶变量的三种坐标。商品语言（Arrow）便于一般均衡与福利；概率语言（\\(\\mathbb{Q}\\)）便于复制与对冲计算；随机折现（\\(m\\)）便于接到欧拉与 Hansen–Jagannathan 界。换坐标不改「线性定价」。风险溢价永远是与 \\(m\\) 的协方差，也永远是 \\(\\mathbb{P}\\) 与 \\(\\mathbb{Q}\\) 的倾斜——同一句话。",-1)),a[6]||(a[6]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：同一地点可以写成经纬度、街道地址或 GPS 度数。Arrow 价格、风险中性概率、SDF 就是定价的三个坐标系——换坐标不换位置，选哪个只看做福利、对冲还是欧拉哪件事顺手。")],-1)),(r(),n(i,null,{default:e(()=>[o(m,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E6%94%AF%E4%BB%98%EF%BC%9A%E6%99%B4%E5%A4%A9%2010%20%E5%85%83%E3%80%81%E9%9B%A8%E5%A4%A9%204%20%E5%85%83%22%5D%0A%20%20X%20--%3E%20AL%5B%22Arrow%20%E8%AF%AD%E8%A8%80%EF%BC%9Ap%20%3D%2010q%E6%99%B4%20%2B%204q%E9%9B%A8%22%5D%0A%20%20X%20--%3E%20MD%5B%22SDF%20%E8%AF%AD%E8%A8%80%EF%BC%9Ap%20%3D%20E%5BmX%5D%22%5D%0A%20%20X%20--%3E%20RN%5B%22%E6%A6%82%E7%8E%87%E8%AF%AD%E8%A8%80%EF%BC%9Ap%20%3D%201%2FRf%20%E4%B9%98%20E%5EQ%5BX%5D%22%5D%0A%20%20AL%20--%3E%20SAME%5B%22%E4%B8%89%E8%80%85%E7%AE%97%E5%87%BA%E5%90%8C%E4%B8%80%E4%B8%AA%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20MD%20--%3E%20SAME%0A%20%20RN%20--%3E%20SAME%0A%20%20SAME%20--%3E%20USE%5B%22%E9%80%89%E5%9D%90%E6%A0%87%E5%8F%AA%E7%9C%8B%E5%93%AA%E7%A7%8D%E8%AE%A1%E7%AE%97%E9%A1%BA%E6%89%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>信息：若价格部分揭示，\\(\\mathcal{F}_t\\) 小于知情者的域流，\\(m\\) 对 \\(\\mathcal{F}_t\\) 可测时定价的是「价格已经知道的」，知情租金是对更大域流的优势，不是 \\(m\\) 不存在。GS 与 FTAP 不互否。</p><p><span class="marginnote">连续状态用密度对 Lebesgue；若 \\(q\\) 对 \\(\\pi\\) 奇异，SDF 没有普通随机变量表示，要用状态价格测度本身。教室里假定绝对连续。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在桥上塞进股权溢价之谜：那是 \\(m=\\beta(c_{t+1}/c_t)^{-\\gamma}\\) 这一特化失败，不是翻译失败。下一课 Lucas 树给出特化的一般均衡来源——禀赋经济里 \\(c\\) 等于股利流的总量。本课只保证：树一旦给出 \\(u&#39;(c)\\)，我们就知道怎么把它读成 \\(q\\) 与 \\(\\mathbb{Q}\\)。</p><p><span class="marginnote">数字实例：两状态各 0.5，晴天回报 2、雨天回报 0.4；取晴天 \\(m=0.8\\)、雨天 \\(m=1.2\\)，则 \\(p=\\mathrm{E}[mx]=0.5\\times(1.6+0.48)=1.04\\)，低于 \\(\\mathrm{E}[m]\\mathrm{E}[x]=1.2\\)。差的 \\(-0.16\\) 是 \\(m\\) 与 \\(x\\) 的协方差：支付偏在坏状态，今天就得多打折——风险溢价的最小算术。</span></p><p>后课默认：\\(q\\)、\\(m\\)、\\(\\mathbb{Q}\\) 一一对应（完全则唯一）。欧拉是均衡选取，FTAP 是无套利存在。条件信息改变投影，不改变会计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(m_s=q_s/\\pi_s\\)，\\(p=\\mathrm{E}[m x]=\\mathrm{E}^{\\mathbb{Q}}[x/B]\\)。</li><li>完全则三者唯一；不完全则三个集合对应。</li><li>欧拉选取其中一个 \\(m\\)；FTAP 只保证集合非空。</li><li>出处：Arrow, 1964；Harrison and Kreps, <em>JET</em> 1979；Hansen and Richard, <em>Econometrica</em> 1987。</li></ul>',8))])}cons